function primarySourceProvider(source) {
  if (source?.provider) return source.provider;
  try {
    const host = new URL(source?.url || '').hostname;
    if (host === 'zh.wikisource.org') return '维基文库录入本';
    if (host === 'www.shidianguji.com' || host === 'shidianguji.com') return '识典古籍数字文本';
    if (host === 'www.dpm.org.cn' || host === 'dpm.org.cn' || host === 'img.dpm.org.cn') return '故宫博物院馆藏页';
    if (host === 'hznews.hangzhou.com.cn') return '杭州日报报道';
    return host || '来源页面';
  } catch {
    return '来源页面';
  }
}

